WITH params AS (SELECT coalesce(%s::text, '') AS ma_loi, coalesce(%s::text, '') AS ma_dvcs, coalesce(%s::text, '') AS status, %s::integer AS authenticated_user_id, %s::integer AS row_limit), scope AS (SELECT p.*, u.user_id AS authorized_user_id, coalesce(u.ds_branchs, '') AS ds_branchs, coalesce(u.is_super, 0) = 1 OR coalesce(u.ds_branchs, '') = '' AS unrestricted FROM params p LEFT JOIN public.userinfo u ON u.user_id = p.authenticated_user_id)
SELECT d.ma_loi, d.ten_loi, d.ten_loi2, d.ds_ma_dvcs, d.nh_nndungmay1, d.nh_nndungmay2, d.nh_nndungmay3, d.status, d.date0, d.time0, d.user_id0, d.date2, d.time2, d.user_id2, d.user_appr, d.date_appr, d.time_appr, count(*) OVER () AS total FROM public.dmnndungmay d CROSS JOIN scope s WHERE s.authorized_user_id IS NOT NULL AND (s.ma_loi = '' OR d.ma_loi = ANY(string_to_array(s.ma_loi, ','))) AND (s.ma_dvcs = '' OR d.ds_ma_dvcs = '' OR string_to_array(d.ds_ma_dvcs, ',') && string_to_array(s.ma_dvcs, ',')) AND (s.status = '' OR d.status::text = ANY(string_to_array(s.status, ','))) AND (s.unrestricted OR d.ds_ma_dvcs = '' OR EXISTS (SELECT 1 FROM unnest(string_to_array(d.ds_ma_dvcs, ',')) x WHERE x = ANY(string_to_array(s.ds_branchs, ',')))) ORDER BY d.ma_loi LIMIT (SELECT row_limit FROM params);
